1	// Backup to a file and import it back. No DOM and no browser storage here: storage goes through the `store` passed in,
2	// so this file can be tested in Node. A backup file is { version: 1, todos: [{ id, title, done, createdAt }] }.
3	const MAX_IMPORT_BYTES = 1048576; // 1 MiB, policy-security#S1. Also the size above which a backup cannot be imported back.
4	
5	const MESSAGES = {
6	  nothingToBackUp: 'Chưa có việc nào để sao lưu.',
7	  backupTooBig: 'File sao lưu đã lưu, nhưng quá lớn nên app không nhập lại được.',
8	  notSaved: 'Thay đổi vừa rồi chưa được lưu. Hãy sao lưu ra file, rồi xoá bớt việc đã xong.',
9	  // One sentence for both cases: the list on screen may already hold changes that an earlier failed save left unsaved.
10	  importNotSaved:
11	    'Chưa nhập được file. Danh sách trên màn hình vẫn nguyên nhưng có thể chưa được lưu, nên đừng tải lại trang. ' +
12	    'Hãy sao lưu ra file, xoá bớt việc đã xong rồi thử lại.',
13	  backedUp: 'Đã sao lưu {n} việc.',
14	  imported: 'Đã nhập {n} việc.',
15	  confirmReplace: 'Thay {n} việc hiện có bằng {m} việc trong file?',
16	  confirmReplaceUnreadable: 'Thay danh sách đã lưu không đọc được bằng {m} việc trong file?',
17	  confirmReplaceUnreadableAndUnsaved:
18	    'Thay danh sách đã lưu không đọc được và {n} việc bạn vừa thêm (chưa lưu) bằng {m} việc trong file?',
19	  emptyFile: 'File này không có việc nào, nên chưa nhập được. Danh sách của bạn vẫn giữ nguyên. Hãy chọn file sao lưu khác.',
20	  notBackup:
21	    'File này không phải file sao lưu của app, nên chưa nhập được. Danh sách của bạn vẫn giữ nguyên. ' +
22	    'Hãy chọn file tạo từ nút "Sao lưu ra file".',
23	  badTodo:
24	    'File sao lưu này bị lỗi, nên chưa nhập được việc nào. Danh sách của bạn vẫn giữ nguyên. Hãy chọn file sao lưu khác.',
25	  fileTooBig:
26	    'File này quá lớn, nên chưa nhập được. Danh sách của bạn vẫn giữ nguyên. Hãy chọn file sao lưu của danh sách ngắn hơn.',
27	  emptyList: 'Chưa có việc nào. Nếu có file sao lưu, hãy bấm "Nhập từ file".',
28	  cannotReadFile: 'Không đọc được file này. Danh sách của bạn vẫn giữ nguyên. Hãy chọn lại file hoặc chọn file khác.',
29	  reading: 'Đang đọc file…',
30	  unreadable:
31	    'Không đọc được danh sách đã lưu trên trình duyệt này. Việc bạn thêm hoặc sửa lúc này sẽ không được lưu. ' +
32	    'Nếu có file sao lưu, hãy bấm "Nhập từ file".',
33	};
34	
35	const TODO_KEYS = ['id', 'title', 'done', 'createdAt'];
36	const FILE_KEYS = ['version', 'todos'];
37	
38	// Counts in app sentences: a dot every three digits from 1,000 up (1.000, 2.001, 12.500), plain below (999).
39	// Not for years or dates, which never go through fill().
40	function formatCount(n) {
41	  return String(n).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
42	}
43	
44	function fill(template, values) {
45	  return template.replace(/\{(\w+)\}/g, (_, k) => formatCount(values[k]));
46	}
47	
48	function pick(t) {
49	  return { id: t.id, title: t.title, done: t.done, createdAt: t.createdAt };
50	}
51	
52	function isObject(v) {
53	  return v !== null && typeof v === 'object' && !Array.isArray(v);
54	}
55	
56	function hasExactKeys(o, keys) {
57	  const own = Object.keys(o);
58	  return own.length === keys.length && keys.every((k) => Object.prototype.hasOwnProperty.call(o, k));
59	}
60	
61	function isValidTodo(t) {
62	  return (
63	    isObject(t) &&
64	    hasExactKeys(t, TODO_KEYS) &&
65	    typeof t.id === 'string' && t.id !== '' &&
66	    typeof t.title === 'string' && t.title.trim() !== '' &&
67	    typeof t.done === 'boolean' &&
68	    typeof t.createdAt === 'number' && Number.isFinite(t.createdAt)
69	  );
70	}
71	
72	function toBackupText(todos) {
73	  return JSON.stringify({ version: 1, todos: todos.map(pick) }, null, 2);
74	}
75	
76	// The customer's own day (local time), not UTC.
77	function backupFileName(date) {
78	  const pad = (n) => String(n).padStart(2, '0');
79	  return `todo-sao-luu-${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}.json`;
80	}
81	
82	function tooBigToImport(text) {
83	  return new TextEncoder().encode(text).length > MAX_IMPORT_BYTES;
84	}
85	
86	// Untrusted input: only JSON.parse, never evaluated. Rejects the whole file on any bad todo (no partial import).
87	function parseBackup(text) {
88	  let data;
89	  try {
90	    data = JSON.parse(text);
91	  } catch {
92	    return { ok: false, message: MESSAGES.notBackup };
93	  }
94	  if (!isObject(data) || !hasExactKeys(data, FILE_KEYS) || data.version !== 1 || !Array.isArray(data.todos)) {
95	    return { ok: false, message: MESSAGES.notBackup };
96	  }
97	  if (data.todos.length === 0) return { ok: false, message: MESSAGES.emptyFile };
98	  const ids = new Set();
99	  const titles = new Set(); // a file that lists the same todo twice (two backups pasted together) is not one this app wrote
100	  for (const t of data.todos) {
101	    const title = isValidTodo(t) && t.title.trim().toLowerCase();
102	    if (!title || ids.has(t.id) || titles.has(title)) return { ok: false, message: MESSAGES.badTodo };
103	    ids.add(t.id);
104	    titles.add(title);
105	  }
106	  return { ok: true, todos: data.todos.map(pick) };
107	}
108	
109	// null when nothing would be lost (empty list, saved list readable), so no confirmation is needed.
110	function confirmText({ readError, current, incoming }) {
111	  if (readError && current === 0) return fill(MESSAGES.confirmReplaceUnreadable, { m: incoming });
112	  if (readError) return fill(MESSAGES.confirmReplaceUnreadableAndUnsaved, { n: current, m: incoming });
113	  if (current === 0) return null;
114	  return fill(MESSAGES.confirmReplace, { n: current, m: incoming });
115	}
116	
117	// After add, toggle or remove. 'skipped' (saved list unreadable) shows nothing extra: the banner already says so.
118	function persist(store, todos) {
119	  return { message: store.save(todos) === 'failed' ? MESSAGES.notSaved : null };
120	}
121	
122	// Returns the list to show and the message. Every path except a successful replace returns `current` unchanged.
123	// Writes only through store.replace, never store.save, so an unreadable saved list is replaced only here.
124	async function importBackup({ store, current, file, ask }) {
125	  const keep = (message) => ({ todos: current, message });
126	  if (file.size > MAX_IMPORT_BYTES) return keep(MESSAGES.fileTooBig);
127	  let text;
128	  try {
129	    text = await file.text();
130	  } catch {
131	    return keep(MESSAGES.cannotReadFile);
132	  }
133	  const parsed = parseBackup(text);
134	  if (!parsed.ok) return keep(parsed.message);
135	  const question = confirmText({ readError: store.readError, current: current.length, incoming: parsed.todos.length });
136	  if (question !== null && !(await ask(question))) return keep(null);
137	  if (store.replace(parsed.todos) !== 'saved') return keep(MESSAGES.importNotSaved);
138	  return { todos: parsed.todos, message: fill(MESSAGES.imported, { n: parsed.todos.length }) };
139	}
140	
141	if (typeof module !== 'undefined') {
142	  module.exports = {
143	    MAX_IMPORT_BYTES, MESSAGES, formatCount, fill, toBackupText, backupFileName, tooBigToImport, parseBackup, confirmText, persist,
144	    importBackup,
145	  };
146	}
147

