1	#!/usr/bin/env node
2	// Simulated users for one environment (SDLC-6, Maintain). The todo app has no server, so there is no 5xx rate to watch.
3	// The stand-in: simulated users run the app's own logic (store.js + backup.js of the release that is live in <env>) and
4	// we count the actions that fail from the user's side. This is SIMULATED traffic, not real users.
5	//
6	//   node scripts/traffic.js --release <dir> --state <file.json> --seed <n> [--users 40] [--fault 0.01]
7	//
8	// One run = one simulated day. Each user keeps their browser storage in <state> between days (so a bad release that
9	// writes something wrong today breaks tomorrow's session, as it would for a real person).
10	// A failed action is one of:
11	//   - not_saved      persist() told the user "not saved" (storage refused the write)
12	//   - import_failed  the user backed up to a file and imported that same file back, and the app refused it
13	//   - exception      the app code threw
14	// Storage refuses a write with probability --fault (the browser quota, a private window...). That is the normal noise.
15	// Prints one JSON line: { actions, failed, rate, by_kind, users, release }.
16	'use strict';
17	const fs = require('node:fs');
18	const path = require('node:path');
19	
20	function arg(name, dflt) {
21	  const i = process.argv.indexOf(name);
22	  return i >= 0 ? process.argv[i + 1] : dflt;
23	}
24	
25	// Small deterministic PRNG (mulberry32): the same seed gives the same day.
26	function rng(seed) {
27	  let a = seed >>> 0;
28	  return () => {
29	    a = (a + 0x6d2b79f5) >>> 0;
30	    let t = a;
31	    t = Math.imul(t ^ (t >>> 15), t | 1);
32	    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
33	    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
34	  };
35	}
36	
37	const release = path.resolve(arg('--release'));
38	const stateFile = arg('--state');
39	const rand = rng(Number(arg('--seed', '1')));
40	const USERS = Number(arg('--users', '40'));
41	const FAULT = Number(arg('--fault', '0.01'));
42	const TAG = arg('--tag', ''); // id prefix of a check run, so it never repeats the ids of the day's real run
43	
44	const { store, STORE_KEY } = require(path.join(release, 'store.js'));
45	const backup = require(path.join(release, 'backup.js'));
46	
47	const state = stateFile && fs.existsSync(stateFile) ? JSON.parse(fs.readFileSync(stateFile, 'utf8')) : {};
48	const WORDS = ['Mua sữa', 'Gọi mẹ', 'Nộp báo cáo', 'Đặt vé', 'Trả tiền điện', 'Đọc sách', 'Tập thể dục', 'Sửa xe', 'Họp nhóm'];
49	
50	function storageFor(user) {
51	  const data = state[user] || {};
52	  state[user] = data;
53	  return {
54	    getItem: (k) => (Object.prototype.hasOwnProperty.call(data, k) ? data[k] : null),
55	    setItem: (k, v) => {
56	      if (rand() < FAULT) {
57	        const e = new Error('quota');
58	        e.name = 'QuotaExceededError';
59	        throw e;
60	      }
61	      data[k] = String(v);
62	    },
63	  };
64	}
65	
66	let actions = 0;
67	let failed = 0;
68	const byKind = { not_saved: 0, import_failed: 0, exception: 0 };
69	const fail = (kind) => {
70	  failed++;
71	  byKind[kind]++;
72	};
73	
74	async function session(user, day) {
75	  globalThis.localStorage = storageFor(user);
76	  let todos = store.load().todos;
77	  const n = 3 + Math.floor(rand() * 6);
78	  for (let i = 0; i < n; i++) {
79	    const r = rand();
80	    actions++;
81	    try {
82	      if (r < 0.45 || todos.length === 0) {
83	        const t = { id: `${TAG}${user}-${day}-${i}`, title: WORDS[Math.floor(rand() * WORDS.length)], done: false,
84	          createdAt: Date.UTC(2026, 9, 1) + day * 86400000 + i };
85	        todos = [...todos, t];
86	        if (backup.persist(store, todos).message) fail('not_saved');
